# application.yml
p200:
  salida-tesoreria: "S500/FILE/INTS/50004S15/{csi}/{fecha}/RANGOS."   # WKS-TIT-E01-RGOS
  sistema-origen: 500

/** Registros de I01-RANGOS (formato de intercambio con Tesorería, campos DISPLAY). */
public sealed interface RangoTesoreria permits RangoTesoreria.Header, RangoTesoreria.Detalle,
                                                RangoTesoreria.Trailer {

    /** WKS-E01-HEADER: tipo 1, sistema 0500, fechas de creación y de proceso. */
    record Header(int sistemaOrigen, LocalDate fechaCreacion, LocalTime horaCreacion,
                  LocalDate fechaIni, LocalDate fechaFin) implements RangoTesoreria {}

    /** WKS-E01-DETALLE: un renglón por producto, persona, rango y par de tasas pagadas. */
    record Detalle(LocalDate fechaProceso,
                   int producto, int instrumento, int moneda,   // PIC 9(11) REDEFINES 4 + 4 + 3
                   BigDecimal limiteInferior, BigDecimal limiteSuperior,   // 9(10)V99
                   BigDecimal saldoActual, BigDecimal saldoPromedio,       // 9(12)V99
                   int numRango, int persona, long numCuentas,
                   BigDecimal tasaNetaPagada, BigDecimal tasaBrutaPagada)  // 9(02)V9(03) -> escala 3
            implements RangoTesoreria {}

    /** WKS-E01-TRAILER: tipo 9, total de detalles y suma de saldos actuales. */
    record Trailer(long totalRegistros, BigDecimal totalSaldos)   // 9(13), 9(16)V99
            implements RangoTesoreria {}
}

/** Formato posicional idéntico al de MCP: Tesorería no cambia su lector. */
@Component
class RangoTesoreriaFormatter implements LineAggregator<RangoTesoreria> {
    @Override public String aggregate(RangoTesoreria r) {
        return switch (r) {
            case RangoTesoreria.Header h  -> Fixed.header(h);    // "1" + "0500" + ...
            case RangoTesoreria.Detalle d -> Fixed.detalle(d);   // decimales implícitos, sin punto
            case RangoTesoreria.Trailer t -> Fixed.trailer(t);   // "9" + 9(13) + 9(16)V99
        };
    }
}

/** WS-TASAS-XCOMUN: 30 instrumentos x 2 tipos de persona x hasta 20 rangos. */
public record TablaTasas(Map<ClaveInstrumento, EnumMap<TipoPersona, List<RangoTasa>>> rangos) {

    /** Escalas del fuente: límites 9(09)V99, tasas 9(04)V9(06). */
    public record RangoTasa(BigDecimal limiteInferior, BigDecimal limiteSuperior,
                            BigDecimal tasaNeta, BigDecimal tasaBruta) {
        static final BigDecimal TOPE_9_09_V99 = new BigDecimal("999999999.99");

        /** MOVE a PIC 9(09)V99 conserva los 9 enteros de la derecha; se replica para no cambiar el archivo. */
        static BigDecimal comoPic9_9V99(BigDecimal v) {
            BigDecimal truncado = v.setScale(2, RoundingMode.DOWN);
            return truncado.remainder(new BigDecimal("1000000000"));
        }
    }

    /** 20030000-CARGA-RANGOS sin pago de rendimiento: un solo rango abierto por persona. */
    static List<RangoTasa> rangoUnico() {
        return List.of(new RangoTasa(BigDecimal.ZERO.setScale(2),
                RangoTasa.comoPic9_9V99(new BigDecimal("9999999999.99")),   // queda 999999999.99
                BigDecimal.ZERO.setScale(6), BigDecimal.ZERO.setScale(6)));
    }
}

@Component
@RequiredArgsConstructor
class AnalizadorTasasS080 {

    /**
     * 20041000-ANALIZA-TASAS. S080 entrega enteros con su número de decimales;
     * el COMPUTE sin ROUNDED trunca a la escala de WKS-IMPPTE (6) y el MOVE a la del destino.
     */
    RangoCrudo analiza(RenglonTarifaS080 r) {
        BigDecimal tasaBruta = BigDecimal.valueOf(r.tasa())
                .movePointLeft(r.decimalesTasa())
                .setScale(6, RoundingMode.DOWN);                 // WKS-TASABRUTA 9(04)V9(06)
        BigDecimal limInf = BigDecimal.valueOf(r.limiteInferior())
                .movePointLeft(r.decimalesInferior())
                .setScale(2, RoundingMode.DOWN);                 // WKS-LIMINF 9(12)V99
        BigDecimal limSup = BigDecimal.valueOf(r.limiteSuperior())
                .movePointLeft(r.decimalesSuperior())
                .setScale(2, RoundingMode.DOWN);                 // WKS-LIMSUP
        return new RangoCrudo(r.persona(), r.plazo(), tasaBruta, limInf, limSup);
    }
}
// movePointLeft es exacto; equivale a dividir entre 10 ** decimales sin pasar por double.

# application.yml
p200:
  tasa-isr: 0.000000          # WS-ISR-0 llega por COPY; su valor no viene en este fuente

@Component
@RequiredArgsConstructor
class CalculoTasaNeta {
    private final P200Properties props;

    /** 20042000-CALCULA-TASAS: la retención de ISR se resta en puntos de tasa, con piso en cero. */
    BigDecimal tasaNeta(BigDecimal tasaBruta) {
        BigDecimal isr = props.tasaIsr().setScale(6, RoundingMode.DOWN);
        return tasaBruta.compareTo(isr) > 0
                ? tasaBruta.subtract(isr)            // resta exacta a 6 decimales
                : BigDecimal.ZERO.setScale(6);
    }
    // La variante que aplicaba 0.85 * ISR a personas morales está comentada en el fuente
    // (líneas 1013 y 1021-1028) y no se traduce.
}

/** 50003000-LEE-BASE-500: filtro de contratos (lectura completa de S500B03CONTRATOS). */
@Bean
@StepScope
JpaCursorItemReader<Contrato> contratosB03(EntityManagerFactory emf) {
    return new JpaCursorItemReaderBuilder<Contrato>()
            .name("contratosB03")
            .entityManagerFactory(emf)
            .queryString("select c from Contrato c")          // FINDN secuencial, base en INQUIRY
            .build();
}

@Component
class SeleccionPuente implements ItemProcessor<Contrato, RegistroPuente> {

    static boolean califica(Contrato c) {
        if (c.getMigradoS111() == 1) return false;                         // migrados a S111 nunca
        boolean statusVigente = c.getStatus() < 2 || c.getStatus() == 5;
        boolean conSaldo = c.getSaldoAnterior().add(c.getSaldoProtegidoAnterior()).signum() > 0;
        return statusVigente || conSaldo;
    }

    @Override
    public RegistroPuente process(Contrato c) {
        return califica(c) ? generaPuente.desde(c, historicos.de(c.getNumContrato())) : null;
    }
}

@Component
@RequiredArgsConstructor
class GeneraPuente {
    private final TablaTasas tabla;
    private final ProcesoContext ctx;        // esMensual: cambio de mes entre fecha línea y fecha batch

    RegistroPuente desde(Contrato c, Historico h) {
        TipoPersona p = c.esPersonaFisicaGrupo() ? TipoPersona.FISICA : TipoPersona.MORAL;  // WS03-88-TP-GFISICA
        BigDecimal total = c.getSaldoAnterior().add(c.getSaldoProtegidoAnterior());

        // Cierre de mes con ciclo anterior: califica por el promedio del ciclo (B06-PROM-CICLO(12)).
        boolean usaPromedio = c.getStatus() != 3 && ctx.esMensual() && h.getFecCicloAnt() > 0;
        BigDecimal saldoRango = usaPromedio ? h.getPromCiclo(12) : total;
        BigDecimal saldoProm  = saldoRango;
        BigDecimal saldoAct   = total;

        List<RangoTasa> rangos = tabla.de(c.instrumento(), p);
        int r = ubicaRango(saldoRango, rangos);
        RangoTasa rt = rangos.get(r - 1);

        boolean status3 = c.getStatus() == 3;
        return new RegistroPuente(c.instrumento(), p, r, rt.limiteInferior(), rt.limiteSuperior(),
                saldoAct, saldoProm,
                status3 ? BigDecimal.ZERO : c.getTasaAnterior(),     // TASANP: tasa neta pagada (B03)
                status3 ? BigDecimal.ZERO : h.getTasaBruta(),        // TASABP: tasa bruta pagada (B06)
                rt.tasaNeta().setScale(3, RoundingMode.DOWN));       // TASANT 9(03)V9(03): trunca a 3
    }

    /** Primer rango cuyo límite superior es mayor o igual al saldo; saldo cero o un rango, el 1. */
    static int ubicaRango(BigDecimal saldo, List<RangoTasa> rangos) {
        int sup = rangos.size();
        if (saldo.signum() == 0 || sup == 1) return 1;
        if (saldo.compareTo(rangos.get(sup - 1).limiteSuperior()) >= 0) return sup;
        for (int r = 1; r <= sup; r++) {
            if (saldo.compareTo(rangos.get(r - 1).limiteSuperior()) <= 0) return r;
        }
        return sup;   // inalcanzable por la condición anterior
    }
}

@Bean
Step generaArchivoTesoreria(JobRepository repo, PlatformTransactionManager tx,
                            FlatFileItemReader<RegistroPuente> puenteOrdenado,     // tras 50007000-SORT-PTE
                            FlatFileItemWriter<RangoTesoreria> rangosWriter) {
    return new StepBuilder("generaArchivoTesoreria", repo)
            .<RegistroPuente, RangoTesoreria>chunk(540, tx)                       // BLOCK 540
            .reader(new GrupoRangoReader(puenteOrdenado))                           // corte de control
            .writer(rangosWriter)
            .listener(new TrailerAcumuladoListener())                              // TOTREGS-T, TOTSDOS-T
            .build();
}

/** 60010100-COMPARA-ANTERIOR: agrupa por (llave, rango, tasa neta pagada, tasa bruta pagada). */
class GrupoRangoReader implements ItemReader<RangoTesoreria.Detalle> {
    private final PeekableItemReader<RegistroPuente> in;

    @Override
    public RangoTesoreria.Detalle read() throws Exception {
        RegistroPuente primero = in.read();
        if (primero == null) return null;
        var g = Grupo.inicia(primero);                                // 60010120-INICIA-REGS
        for (RegistroPuente sig; (sig = in.peek()) != null && g.mismaLlave(sig); ) {
            g.suma(in.read());                                        // 60012000-SUMA-IGUAL
        }
        return g.comoDetalle();                                       // 60015000-ESCRIBE-ARCHIVO
    }
}

# application.yml
p200:
  puente:
    conservar: true      # comportamiento actual: CLOSE WITH SAVE; RN-S500-759 espera PURGE

/**
 * En MCP se escriben un registro de ceros y uno de nueves para que el SORT por producto
 * los deje al principio y al final, y en la lectura posterior se reemplazan por el header
 * y el trailer reales. En Java no hace falta: el writer conoce los totales al cerrar.
 */
@Bean
@StepScope
FlatFileItemWriter<RangoTesoreria> rangosWriter(P200Properties props, ProcesoContext ctx,
                                                TrailerAcumuladoListener totales) {
    return new FlatFileItemWriterBuilder<RangoTesoreria>()
            .name("rangosTesoreria")
            .resource(new FileSystemResource(props.salidaTesoreria(ctx)))
            .lineAggregator(new RangoTesoreriaFormatter())
            .headerCallback(w -> w.write(Fixed.header(RangoTesoreria.Header.de(ctx))))
            .footerCallback(w -> w.write(Fixed.trailer(new RangoTesoreria.Trailer(
                    totales.registros(), totales.saldoActual()))))
            .build();
}
// El orden final (producto, persona, rango, tasas) se obtiene ordenando antes de escribir,
// con un step de ordenamiento externo o con la consulta que alimenta el puente.
